//! Items the code generated by `#[derive(UiType)]` names. Not part of the stable API.

use std::fmt::{Debug, Display, Formatter, Result};
use std::str::FromStr;

pub use crate::{
  ArgInfo, AttachedPropertyInfo, AttachedTarget, ContentInfo, EventInfo, HasGroup, OverrideDefaults, PropertyGroup,
  PropertyGroupInfo, PropertyInfo, PropertyRef, RustExpr, ToRust, TypeInfo, UiCollection, UiType, ValueError,
  ValueProviderInfo, Whitespace, WithChildren, register_type,
};
pub use artic_core::Object;
pub use artic_core::event::Event;
pub use artic_core::property::{
  Affects, AnyProperty, AttachedKey, Inheritance, ParseEnumError, Property, PropertyKey, SharedKey, inherit,
};
pub use artic_core::tree::{Handle, NodeId, UiTree};
pub use std::marker::PhantomData;

/// Wraps a property's value type for the check below.
pub struct ValueCheck<T>(pub PhantomData<T>);

impl<T> Debug for ValueCheck<T> {
  fn fmt(&self, formatter: &mut Formatter<'_>) -> Result {
    formatter.write_str("ValueCheck")
  }
}

/// What `literal` returns for a property whose value is an element.
const TAKES_AN_ELEMENT: &str = "this property takes an element, not text";

/// The value type can be written as text, and written back as Rust.
pub trait ViaFromStr {
  fn value_must_parse_from_text_and_implement_torust_or_derive_uitype(&self) {}

  /// Parses `text` and writes the value it gives.
  fn write_literal(&self, text: &str, out: &mut RustExpr) -> std::result::Result<(), String>;
}

impl<T> ViaFromStr for ValueCheck<T>
where
  T: FromStr + ToRust,
  T::Err: Display,
{
  fn write_literal(&self, text: &str, out: &mut RustExpr) -> std::result::Result<(), String> {
    let value: T = text.parse().map_err(|error: T::Err| error.to_string())?;
    value.to_rust(out);
    Ok(())
  }
}

/// The value type is itself a UI type, written as an object.
pub trait ViaUiType {
  fn value_must_parse_from_text_and_implement_torust_or_derive_uitype(&self) {}

  /// Refuses text: the value is an element.
  fn write_literal(&self, _text: &str, _out: &mut RustExpr) -> std::result::Result<(), String> {
    Err(TAKES_AN_ELEMENT.to_owned())
  }
}

impl<T: UiType> ViaUiType for &ValueCheck<T> {}

/// The value is a child element, filled in by the element written inside.
pub trait ViaChild {
  fn value_must_parse_from_text_and_implement_torust_or_derive_uitype(&self) {}

  /// Refuses text: the value is an element.
  fn write_literal(&self, _text: &str, _out: &mut RustExpr) -> std::result::Result<(), String> {
    Err(TAKES_AN_ELEMENT.to_owned())
  }
}

impl ViaChild for &&ValueCheck<NodeId> {}

/// The function `PropertyInfo::literal` holds for a property of value type `$value`: `Some` with
/// the `literals` feature, `None` without, so an app's registry keeps no `ToRust` code.
#[cfg(feature = "literals")]
#[doc(hidden)]
#[macro_export]
macro_rules! __literal {
  ($value:ty) => {
    ::core::option::Option::Some({
      fn literal(text: &str, out: &mut $crate::RustExpr) -> ::core::result::Result<(), ::std::string::String> {
        use $crate::__private::{ViaChild as _, ViaFromStr as _, ViaUiType as _};
        (&&$crate::__private::ValueCheck::<$value>($crate::__private::PhantomData)).write_literal(text, out)
      }
      literal as $crate::WriteLiteral
    })
  };
}

/// The function `PropertyInfo::literal` holds for a property of value type `$value`: `Some` with
/// the `literals` feature, `None` without, so an app's registry keeps no `ToRust` code.
#[cfg(not(feature = "literals"))]
#[doc(hidden)]
#[macro_export]
macro_rules! __literal {
  ($value:ty) => {
    ::core::option::Option::None
  };
}

pub use crate::__literal as literal;

/// Whether `a` and `b` are the same text, in const code.
const fn same_text(a: &str, b: &str) -> bool {
  let (a, b) = (a.as_bytes(), b.as_bytes());
  if a.len() != b.len() {
    return false;
  }
  let mut index = 0;
  while index < a.len() {
    if a[index] != b[index] {
      return false;
    }
    index += 1;
  }
  true
}

/// Whether a group's `properties` hold a field named `name`.
pub const fn group_has_field(properties: &[PropertyInfo], name: &str) -> bool {
  let mut index = 0;
  while index < properties.len() {
    if same_text(properties[index].field, name) {
      return true;
    }
    index += 1;
  }
  false
}

/// Whether two groups' `properties` hold a field of one name.
pub const fn groups_share_field(a: &[PropertyInfo], b: &[PropertyInfo]) -> bool {
  let mut index = 0;
  while index < a.len() {
    if group_has_field(b, a[index].field) {
      return true;
    }
    index += 1;
  }
  false
}

/// Compiles only if `T` is a collection of child elements.
pub const fn assert_collection<T: UiCollection>() {}

/// Compiles only if `T` is a property group.
pub const fn assert_property_group<T: PropertyGroup>() {}

/// The content a flattened group gives the type that holds it in `field`.
pub const fn group_content(field: &'static str, info: Option<&'static PropertyInfo>) -> Option<ContentInfo> {
  match info {
    Some(info) => Some(ContentInfo::Property(PropertyRef {
      group: Some(field),
      info,
    })),
    None => None,
  }
}

/// The one content candidate that is set, if any.
///
/// # Panics
///
/// At compile time, when more than one is set: a type has at most one content member, counting the
/// groups it flattens.
pub const fn one_content(candidates: &[Option<ContentInfo>]) -> Option<ContentInfo> {
  let mut found = None;
  let mut index = 0;
  while index < candidates.len() {
    if let Some(candidate) = candidates[index] {
      assert!(
        found.is_none(),
        "a type has at most one `#[ui(content)]` member, counting the groups it flattens"
      );
      found = Some(candidate);
    }
    index += 1;
  }
  found
}

/// A key a field may name its own default beside: a property key, through any number of
/// references. An attached key brings its own default, and two could disagree.
#[diagnostic::on_unimplemented(
  message = "`default` can't go beside an attached key",
  label = "this attached key already gives the field its default",
  note = "remove `default = ...`; the field starts at the attached property's default"
)]
pub trait TakesDefault {}

impl<T> TakesDefault for PropertyKey<T> {}

impl<K: TakesDefault + ?Sized> TakesDefault for &K {}

/// Returns `value`, the default a field names beside `key`, once the compiler has checked that
/// `key` may take one.
pub fn default_beside<K: TakesDefault + ?Sized, T>(key: &K, value: T) -> T {
  let _ = key;
  value
}

#[cfg(test)]
mod tests {
  use super::*;

  #[derive(Debug)]
  struct Gauge;

  impl UiType for Gauge {
    const TYPE_INFO: &'static TypeInfo = &GAUGE;
  }

  static GAUGE: TypeInfo = TypeInfo {
    name: "Gauge",
    rust_path: "tests::Gauge",
    new: |_| unreachable!("never created"),
    content: None,
    is_collection: false,
    properties: &[],
    groups: &[],
    events: &[],
    attached_properties: &[],
    value_provider: None,
    whitespace: Whitespace::Collapse,
  };

  // The check resolves for a FromStr type, a UI type and a child node. A type that is none of
  // them fails to compile, which the derive's compile-fail tests cover.
  #[test]
  #[allow(
    clippy::needless_borrow,
    reason = "the extra references pick the matching check, as in generated code"
  )]
  fn value_check_accepts_text_object_and_child_values() {
    (&&ValueCheck::<f32>(PhantomData)).value_must_parse_from_text_and_implement_torust_or_derive_uitype();
    (&&ValueCheck::<Gauge>(PhantomData)).value_must_parse_from_text_and_implement_torust_or_derive_uitype();
    (&&ValueCheck::<NodeId>(PhantomData)).value_must_parse_from_text_and_implement_torust_or_derive_uitype();
  }
}
